//! The golden corpus: the Python engine's last word, kept as a fixture once it is gone.
//!
//! PLAN.md §14.1, Phase 3.1 step 1. Python and Rust were byte-identical over 700k games
//! compared at every step; this file set is the receipt. It was generated by the build
//! frozen as `oracle-v1`, independently recomputed by the Python engine and encoder before
//! they were deleted, and from then on every Rust build is checked against it. Nothing here
//! is ever regenerated to make a test pass: a mismatch means the engine plays a different
//! game, and the only fixes are to repair the regression or to bump a version and re-sign.
//!
//! One file per `(map, seat count)`, `tests/golden/corpus/<map>-<n>p.bin`, three sections:
//!
//! * **Random drive**, seeds `0..RANDOM_SEEDS`. The action at each step is drawn from the
//!   *sorted* legal list by `stream(seed, "corpus", "policy")`, so the drive is a pure
//!   function of the seed and needs no stored actions. Each game keeps its step count, its
//!   final scores, its winners, and a **hash chain** (below).
//! * **Observation digests** for the first `OBS_SEEDS` of those games, every seat's
//!   observation at every `SAMPLE_EVERY`-th position plus the terminal one.
//! * **Heuristic games**: H3 self-play, actions stored, chain and observation digests.
//!   Random play rarely completes a ticket or builds a long trunk, and `remaining_cost`,
//!   `fragility` and `on_my_steiner_tree` are exactly the features Phase 3.2 rewrites, so
//!   the encoder is also signed off on positions a competent player actually reaches.
//!   Storing the actions decouples the check from H3 itself: a re-tuned H3 cannot break it.
//!
//! **The chain** is blake2b-64 over, for every position from setup to the terminal:
//! `state_hash`, `position_hash` (u64 each), the legal-action count (u16) and the sorted
//! legal actions (u16 each); then, once, the terminal settlement: per seat the eight
//! `Breakdown` fields at their natural widths and the return's IEEE-754 bits, then the
//! winners mask. Everything little-endian. One u64 per game is enough to notice anything;
//! *where* is the oracle differential's job, which compares the same quantities step by
//! step.
//!
//! **Observation digests come in two halves**, discrete slots and continuous ones, because
//! Phase 3.2's contract is "discrete bit-exact, continuous within 1e-6" and a single digest
//! could only ever say bit-exact. The discrete half is checked exactly forever. The
//! continuous half is checked exactly against `oracle-v1`, and the live crate is checked
//! against `oracle-v1` within the tolerance -- so the chain from Python to today never has a
//! gap, even if a continuous feature legitimately moves in its last bit.

use std::ops::Range;
use std::path::PathBuf;

use blake2b_simd::{Params, State as Hasher};
use rayon::prelude::*;
use ttr_core::board::all_boards;
use ttr_core::heuristic::{Heuristic, HeuristicParams, Tier};
use ttr_core::obs_spec::{Kind, spec_for};
use ttr_core::rng::{Part, stream};

use crate::engine::{Engine, Live, Terminal};

pub const MAGIC: &[u8; 4] = b"TTRG";
/// The layout of this file, not of anything it describes.
pub const FORMAT_VERSION: u8 = 1;

pub const RANDOM_SEEDS: u32 = 10_000;
pub const OBS_SEEDS: u32 = 500;
pub const HEURISTIC_SEEDS: u32 = 200;
/// Coprime with nothing in particular: it only has to not line up with the turn
/// structure, so the samples land in every phase.
pub const SAMPLE_EVERY: u8 = 7;

/// A game that has not ended by now is a hang, not a long game.
const MAX_STEPS: usize = 20_000;

/// Which observation slots are continuous, per board.
pub struct ObsMask {
    pub continuous: Vec<bool>,
}

impl ObsMask {
    /// From the spec's field kinds: ratios are the continuous half, flags the discrete.
    ///
    /// The kinds are part of the `OBS_VERSION`ed table, so a reclassification is a version
    /// bump and a re-sign, never a silent change to which half a slot feeds. They were
    /// checked equal to the lists the corpus was first generated under when the table
    /// moved into Rust.
    pub fn for_map(map: &str) -> Self {
        let spec = spec_for(map);
        let mut continuous = vec![false; spec.size];
        for block in &spec.blocks {
            for field in &block.fields {
                for entity in 0..block.count {
                    let start = block.offset + entity * block.stride + field.offset;
                    continuous[start..start + field.width].fill(field.kind == Kind::Ratio);
                }
            }
        }
        Self { continuous }
    }
}

/// The two halves of a game's observation digest.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct ObsDigest {
    pub discrete: u64,
    pub continuous: u64,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Header {
    pub contract_version: u8,
    pub obs_version: u32,
    pub map: String,
    pub n_players: u8,
    pub data_hash: [u8; 16],
    pub rules_hash: [u8; 16],
    pub sample_every: u8,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RandomGame {
    pub steps: u16,
    pub chain: u64,
    pub scores: Vec<i16>,
    pub winners: u8,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct RecordedGame {
    pub actions: Vec<u16>,
    pub chain: u64,
    pub scores: Vec<i16>,
    pub winners: u8,
    pub obs: ObsDigest,
}

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Corpus {
    pub header: Header,
    /// Seed `i` is entry `i`.
    pub random: Vec<RandomGame>,
    /// Observation digests for `random[..random_obs.len()]`.
    pub random_obs: Vec<ObsDigest>,
    /// H3 self-play; seed `i` is entry `i`.
    pub heuristic: Vec<RecordedGame>,
}

/// Every `(map, seat count)` the engine supports, in file order.
pub fn configs() -> Vec<(&'static str, usize)> {
    all_boards()
        .iter()
        .flat_map(|b| {
            (usize::from(b.raw.min_players)..=usize::from(b.raw.max_players)).map(|n| (b.name, n))
        })
        .collect()
}

pub fn corpus_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../tests/golden/corpus")
}

pub fn corpus_path(map: &str, n_players: usize) -> PathBuf {
    corpus_dir().join(format!("{map}-{n_players}p.bin"))
}

// ---------------------------------------------------------------------------
// Hashing
// ---------------------------------------------------------------------------

/// blake2b with an 8-byte digest: Python's `hashlib.blake2b(digest_size=8)`.
fn hasher() -> Hasher {
    Params::new().hash_length(8).to_state()
}

fn finish(h: &Hasher) -> u64 {
    let digest = h.finalize();
    u64::from_le_bytes(digest.as_bytes().try_into().expect("an 8-byte digest"))
}

fn fold_position<E: Engine>(engine: &E, state: &E::State, legal: &[u16], chain: &mut Hasher) {
    chain.update(&engine.state_hash(state).to_le_bytes());
    chain.update(&engine.position_hash(state).to_le_bytes());
    chain.update(&(legal.len() as u16).to_le_bytes());
    for action in legal {
        chain.update(&action.to_le_bytes());
    }
}

fn fold_terminal(terminal: &Terminal, chain: &mut Hasher) {
    for (b, ret) in terminal.breakdown.iter().zip(&terminal.returns) {
        chain.update(&(b[0] as i16).to_le_bytes()); // routes
        chain.update(&[b[1] as u8, b[2] as u8]); // tickets made, missed
        chain.update(&(b[3] as i16).to_le_bytes()); // ticket points
        chain.update(&(b[4] as i16).to_le_bytes()); // longest-path bonus
        chain.update(&(b[5] as u16).to_le_bytes()); // longest trail
        chain.update(&[b[6] as u8]); // completed
        chain.update(&(b[7] as i16).to_le_bytes()); // total
        chain.update(&ret.to_bits().to_le_bytes());
    }
    chain.update(&[terminal.winners_mask()]);
}

struct ObsDigester {
    discrete: Hasher,
    continuous: Hasher,
    buffer: Vec<f32>,
    discrete_bytes: Vec<u8>,
    continuous_bytes: Vec<u8>,
}

impl ObsDigester {
    fn new(size: usize) -> Self {
        Self {
            discrete: hasher(),
            continuous: hasher(),
            buffer: vec![0.0; size],
            discrete_bytes: Vec::with_capacity(4 * size),
            continuous_bytes: Vec::with_capacity(4 * size),
        }
    }

    /// Every seat's observation, seat 0 first.
    fn fold<E: Engine>(
        &mut self,
        engine: &E,
        state: &mut E::State,
        mask: &ObsMask,
    ) -> Result<(), String> {
        for player in 0..engine.n_players() {
            engine.encode(state, player, &mut self.buffer);
            self.discrete_bytes.clear();
            self.continuous_bytes.clear();
            for (slot, &value) in self.buffer.iter().enumerate() {
                if mask.continuous[slot] {
                    self.continuous_bytes
                        .extend_from_slice(&value.to_le_bytes());
                } else {
                    if value.to_bits() != 0.0f32.to_bits() && value != 1.0 {
                        return Err(format!(
                            "seat {player}: discrete slot {slot} holds {value}, not 0 or 1"
                        ));
                    }
                    self.discrete_bytes.extend_from_slice(&value.to_le_bytes());
                }
            }
            self.discrete.update(&self.discrete_bytes);
            self.continuous.update(&self.continuous_bytes);
        }
        Ok(())
    }

    fn finish(&self) -> ObsDigest {
        ObsDigest {
            discrete: finish(&self.discrete),
            continuous: finish(&self.continuous),
        }
    }
}

// ---------------------------------------------------------------------------
// Drives
// ---------------------------------------------------------------------------

/// One game, folded.
#[derive(Clone, Debug)]
pub struct Trace {
    pub actions: Vec<u16>,
    pub chain: u64,
    pub terminal: Terminal,
    pub obs: Option<ObsDigest>,
}

/// Play one game from `seed`, folding every position into the chain.
///
/// `choose` is handed the state, the sorted legal list and the step index, and must return
/// a legal action -- a drive that hands back an illegal one is reported, never stepped.
pub fn trace<E: Engine>(
    engine: &E,
    seed: u64,
    mask: Option<&ObsMask>,
    mut choose: impl FnMut(&mut E::State, &[u16], usize) -> Result<u16, String>,
) -> Result<Trace, String> {
    let mut state = engine.initial(seed);
    let mut chain = hasher();
    let mut digester = mask.map(|_| ObsDigester::new(engine.obs_size()));
    let mut actions = Vec::new();
    let mut step = 0usize;
    loop {
        let legal = engine.legal(&state);
        fold_position(engine, &state, &legal, &mut chain);
        let done = engine.is_terminal(&state);
        let sampled = step % usize::from(SAMPLE_EVERY) == 0 || done;
        if let (Some(d), Some(m), true) = (digester.as_mut(), mask, sampled) {
            d.fold(engine, &mut state, m)
                .map_err(|e| format!("step {step}: {e}"))?;
        }
        if done {
            break;
        }
        let action = choose(&mut state, &legal, step)?;
        if legal.binary_search(&action).is_err() {
            return Err(format!("step {step}: action {action} is not legal here"));
        }
        engine.step(&mut state, action);
        actions.push(action);
        step += 1;
        if step > MAX_STEPS {
            return Err(format!("no terminal after {MAX_STEPS} steps"));
        }
    }
    let terminal = engine.terminal(&mut state);
    fold_terminal(&terminal, &mut chain);
    Ok(Trace {
        actions,
        chain: finish(&chain),
        terminal,
        obs: digester.map(|d| d.finish()),
    })
}

/// The random drive: uniform over the sorted legal list, from the seed's own stream.
pub fn random_trace<E: Engine>(
    engine: &E,
    seed: u64,
    mask: Option<&ObsMask>,
) -> Result<Trace, String> {
    let mut policy = stream(seed, &[Part::Str("corpus"), Part::Str("policy")]);
    trace(engine, seed, mask, |_, legal, _| {
        Ok(legal[policy.below(legal.len() as u32) as usize])
    })
}

/// Replay recorded actions. Running out early, or finishing with actions left, is an error.
pub fn replay_trace<E: Engine>(
    engine: &E,
    seed: u64,
    actions: &[u16],
    mask: Option<&ObsMask>,
) -> Result<Trace, String> {
    let traced = trace(engine, seed, mask, |_, _, step| {
        actions
            .get(step)
            .copied()
            .ok_or_else(|| format!("the game outlived its {} recorded actions", actions.len()))
    })?;
    if traced.actions.len() != actions.len() {
        return Err(format!(
            "the game ended after {} of {} recorded actions",
            traced.actions.len(),
            actions.len()
        ));
    }
    Ok(traced)
}

/// H3 self-play, with every seat's stream rooted at agent seed 0.
pub fn heuristic_trace(engine: &Live, seed: u64, mask: Option<&ObsMask>) -> Result<Trace, String> {
    let n = engine.n_players();
    let mut agents: Vec<Heuristic> = (0..n)
        .map(|seat| {
            let mut agent = Heuristic::new(Tier::H3, HeuristicParams::default(), 0);
            agent.begin_game(seat, seed);
            agent
        })
        .collect();
    trace(engine, seed, mask, |state, _, _| {
        let seat = usize::from(state.current_player());
        Ok(agents[seat].act(state))
    })
}

// ---------------------------------------------------------------------------
// Generation and checking
// ---------------------------------------------------------------------------

fn hex16(hex: &str) -> [u8; 16] {
    let mut out = [0u8; 16];
    assert_eq!(hex.len(), 32, "expected 32 hex digits, got {hex:?}");
    for (i, byte) in out.iter_mut().enumerate() {
        *byte = u8::from_str_radix(&hex[2 * i..2 * i + 2], 16).expect("a hex digest");
    }
    out
}

/// The header the live crate would write for this configuration today.
pub fn current_header(map: &str, n_players: usize) -> Header {
    let engine = Live::new(map, n_players);
    let game = engine.game();
    Header {
        contract_version: ttr_core::CONTRACT_VERSION,
        obs_version: ttr_core::obs::obs_version(),
        map: map.to_string(),
        n_players: n_players as u8,
        data_hash: hex16(game.board.data_hash),
        rules_hash: hex16(&game.cfg.rules_hash()),
        sample_every: SAMPLE_EVERY,
    }
}

/// Generate one configuration's corpus with the live crate.
pub fn generate(map: &str, n_players: usize) -> Corpus {
    let engine = Live::new(map, n_players);
    let mask = ObsMask::for_map(map);
    let label = format!("{map} {n_players}P");

    let random: Vec<Trace> = (0..RANDOM_SEEDS)
        .into_par_iter()
        .map(|seed| {
            let m = (seed < OBS_SEEDS).then_some(&mask);
            random_trace(&engine, u64::from(seed), m)
                .unwrap_or_else(|e| panic!("{label} random seed {seed}: {e}"))
        })
        .collect();
    let heuristic: Vec<Trace> = (0..HEURISTIC_SEEDS)
        .into_par_iter()
        .map(|seed| {
            heuristic_trace(&engine, u64::from(seed), Some(&mask))
                .unwrap_or_else(|e| panic!("{label} heuristic seed {seed}: {e}"))
        })
        .collect();

    Corpus {
        header: current_header(map, n_players),
        random_obs: random[..OBS_SEEDS as usize]
            .iter()
            .map(|t| t.obs.expect("sampled"))
            .collect(),
        random: random
            .iter()
            .map(|t| RandomGame {
                steps: u16::try_from(t.actions.len()).expect("a game fits in u16 steps"),
                chain: t.chain,
                scores: t.terminal.scores.clone(),
                winners: t.terminal.winners_mask(),
            })
            .collect(),
        heuristic: heuristic
            .into_iter()
            .map(|t| RecordedGame {
                chain: t.chain,
                scores: t.terminal.scores.clone(),
                winners: t.terminal.winners_mask(),
                obs: t.obs.expect("sampled"),
                actions: t.actions,
            })
            .collect(),
    }
}

/// Which games a check re-derives. The fast tier takes prefixes; the slow tier takes all.
#[derive(Clone, Debug)]
pub struct Scope {
    pub random: Range<u32>,
    pub obs: Range<u32>,
    pub heuristic: Range<u32>,
    /// Compare the continuous observation half too. Off only where Phase 3.2's tolerance
    /// applies and the comparison is made against `oracle-v1` instead.
    pub continuous: bool,
}

impl Scope {
    pub fn all() -> Self {
        Self {
            random: 0..RANDOM_SEEDS,
            obs: 0..OBS_SEEDS,
            heuristic: 0..HEURISTIC_SEEDS,
            continuous: true,
        }
    }

    pub fn prefix(random: u32, obs: u32, heuristic: u32) -> Self {
        Self {
            random: 0..random,
            obs: 0..obs,
            heuristic: 0..heuristic,
            continuous: true,
        }
    }
}

fn compare_obs(
    label: &str,
    got: ObsDigest,
    want: ObsDigest,
    continuous: bool,
) -> Result<(), String> {
    if got.discrete != want.discrete {
        return Err(format!(
            "{label}: discrete observation digest {:016x} != recorded {:016x}",
            got.discrete, want.discrete
        ));
    }
    if continuous && got.continuous != want.continuous {
        return Err(format!(
            "{label}: continuous observation digest {:016x} != recorded {:016x}",
            got.continuous, want.continuous
        ));
    }
    Ok(())
}

/// Re-derive the games in `scope` with `engine` and compare. Returns games checked.
///
/// Errors name the section, the seed and the first quantity that differs, lowest seed
/// first, so the report is the same however rayon schedules the work.
pub fn check<E: Engine>(engine: &E, corpus: &Corpus, scope: &Scope) -> Result<usize, String> {
    let h = &corpus.header;
    if engine.map_name() != h.map || engine.n_players() != usize::from(h.n_players) {
        return Err(format!(
            "corpus is {} {}P, engine is {} {}P",
            h.map,
            h.n_players,
            engine.map_name(),
            engine.n_players()
        ));
    }
    let mask = ObsMask::for_map(&h.map);
    let label = format!("{} {}P", h.map, h.n_players);

    let random: Vec<Result<(), String>> = scope
        .random
        .clone()
        .into_par_iter()
        .map(|seed| {
            let want = &corpus.random[seed as usize];
            let sampled = scope.obs.contains(&seed);
            let got = random_trace(engine, u64::from(seed), sampled.then_some(&mask))
                .map_err(|e| format!("{label} random seed {seed}: {e}"))?;
            let here = format!("{label} random seed {seed}");
            if got.actions.len() != usize::from(want.steps) {
                return Err(format!(
                    "{here}: {} steps, recorded {}",
                    got.actions.len(),
                    want.steps
                ));
            }
            if got.terminal.scores != want.scores {
                return Err(format!(
                    "{here}: scores {:?}, recorded {:?}",
                    got.terminal.scores, want.scores
                ));
            }
            if got.terminal.winners_mask() != want.winners {
                return Err(format!(
                    "{here}: winners {:#b}, recorded {:#b}",
                    got.terminal.winners_mask(),
                    want.winners
                ));
            }
            if got.chain != want.chain {
                return Err(format!(
                    "{here}: chain {:016x} != recorded {:016x}",
                    got.chain, want.chain
                ));
            }
            if sampled {
                compare_obs(
                    &here,
                    got.obs.expect("sampled"),
                    corpus.random_obs[seed as usize],
                    scope.continuous,
                )?;
            }
            Ok(())
        })
        .collect();
    random.into_iter().collect::<Result<(), String>>()?;

    let heuristic: Vec<Result<(), String>> = scope
        .heuristic
        .clone()
        .into_par_iter()
        .map(|seed| {
            let want = &corpus.heuristic[seed as usize];
            let here = format!("{label} heuristic seed {seed}");
            let got = replay_trace(engine, u64::from(seed), &want.actions, Some(&mask))
                .map_err(|e| format!("{here}: {e}"))?;
            if got.terminal.scores != want.scores {
                return Err(format!(
                    "{here}: scores {:?}, recorded {:?}",
                    got.terminal.scores, want.scores
                ));
            }
            if got.terminal.winners_mask() != want.winners {
                return Err(format!("{here}: winners differ"));
            }
            if got.chain != want.chain {
                return Err(format!(
                    "{here}: chain {:016x} != recorded {:016x}",
                    got.chain, want.chain
                ));
            }
            compare_obs(&here, got.obs.expect("sampled"), want.obs, scope.continuous)
        })
        .collect();
    heuristic.into_iter().collect::<Result<(), String>>()?;

    Ok(scope.random.len() + scope.heuristic.len())
}

// ---------------------------------------------------------------------------
// Wire format
// ---------------------------------------------------------------------------

struct Reader<'a> {
    data: &'a [u8],
    at: usize,
}

impl<'a> Reader<'a> {
    fn take(&mut self, n: usize) -> Result<&'a [u8], String> {
        let end = self.at + n;
        if end > self.data.len() {
            return Err(format!("truncated at byte {} (wanted {n} more)", self.at));
        }
        let out = &self.data[self.at..end];
        self.at = end;
        Ok(out)
    }
    fn u8(&mut self) -> Result<u8, String> {
        Ok(self.take(1)?[0])
    }
    fn u16(&mut self) -> Result<u16, String> {
        Ok(u16::from_le_bytes(
            self.take(2)?.try_into().expect("2 bytes"),
        ))
    }
    fn i16(&mut self) -> Result<i16, String> {
        Ok(i16::from_le_bytes(
            self.take(2)?.try_into().expect("2 bytes"),
        ))
    }
    fn u32(&mut self) -> Result<u32, String> {
        Ok(u32::from_le_bytes(
            self.take(4)?.try_into().expect("4 bytes"),
        ))
    }
    fn u64(&mut self) -> Result<u64, String> {
        Ok(u64::from_le_bytes(
            self.take(8)?.try_into().expect("8 bytes"),
        ))
    }
    fn hash16(&mut self) -> Result<[u8; 16], String> {
        Ok(self.take(16)?.try_into().expect("16 bytes"))
    }
}

impl Corpus {
    /// Little-endian, no padding, every count before the thing it counts.
    pub fn to_bytes(&self) -> Vec<u8> {
        let h = &self.header;
        let n = usize::from(h.n_players);
        let mut out = Vec::new();
        out.extend_from_slice(MAGIC);
        out.push(FORMAT_VERSION);
        out.push(h.contract_version);
        out.extend_from_slice(&h.obs_version.to_le_bytes());
        out.push(h.n_players);
        out.push(u8::try_from(h.map.len()).expect("a short map name"));
        out.extend_from_slice(h.map.as_bytes());
        out.extend_from_slice(&h.data_hash);
        out.extend_from_slice(&h.rules_hash);
        out.push(h.sample_every);
        out.extend_from_slice(&(self.random.len() as u32).to_le_bytes());
        out.extend_from_slice(&(self.random_obs.len() as u32).to_le_bytes());
        out.extend_from_slice(&(self.heuristic.len() as u32).to_le_bytes());
        for g in &self.random {
            assert_eq!(g.scores.len(), n);
            out.extend_from_slice(&g.steps.to_le_bytes());
            out.extend_from_slice(&g.chain.to_le_bytes());
            for s in &g.scores {
                out.extend_from_slice(&s.to_le_bytes());
            }
            out.push(g.winners);
        }
        for d in &self.random_obs {
            out.extend_from_slice(&d.discrete.to_le_bytes());
            out.extend_from_slice(&d.continuous.to_le_bytes());
        }
        for g in &self.heuristic {
            assert_eq!(g.scores.len(), n);
            out.extend_from_slice(
                &u16::try_from(g.actions.len())
                    .expect("a game fits in u16 steps")
                    .to_le_bytes(),
            );
            for a in &g.actions {
                out.extend_from_slice(&a.to_le_bytes());
            }
            out.extend_from_slice(&g.chain.to_le_bytes());
            for s in &g.scores {
                out.extend_from_slice(&s.to_le_bytes());
            }
            out.push(g.winners);
            out.extend_from_slice(&g.obs.discrete.to_le_bytes());
            out.extend_from_slice(&g.obs.continuous.to_le_bytes());
        }
        out
    }

    pub fn from_bytes(data: &[u8]) -> Result<Self, String> {
        let mut r = Reader { data, at: 0 };
        if r.take(4)? != MAGIC {
            return Err("not a golden corpus file (bad magic)".into());
        }
        let format = r.u8()?;
        if format != FORMAT_VERSION {
            return Err(format!(
                "corpus format {format}, this reader is {FORMAT_VERSION}"
            ));
        }
        let contract_version = r.u8()?;
        let obs_version = r.u32()?;
        let n_players = r.u8()?;
        let name_len = usize::from(r.u8()?);
        let map = String::from_utf8(r.take(name_len)?.to_vec()).map_err(|e| e.to_string())?;
        let data_hash = r.hash16()?;
        let rules_hash = r.hash16()?;
        let sample_every = r.u8()?;
        let n_random = r.u32()? as usize;
        let n_obs = r.u32()? as usize;
        let n_heuristic = r.u32()? as usize;
        let n = usize::from(n_players);

        let mut random = Vec::with_capacity(n_random);
        for _ in 0..n_random {
            let steps = r.u16()?;
            let chain = r.u64()?;
            let scores = (0..n).map(|_| r.i16()).collect::<Result<_, _>>()?;
            let winners = r.u8()?;
            random.push(RandomGame {
                steps,
                chain,
                scores,
                winners,
            });
        }
        let mut random_obs = Vec::with_capacity(n_obs);
        for _ in 0..n_obs {
            random_obs.push(ObsDigest {
                discrete: r.u64()?,
                continuous: r.u64()?,
            });
        }
        let mut heuristic = Vec::with_capacity(n_heuristic);
        for _ in 0..n_heuristic {
            let len = usize::from(r.u16()?);
            let actions = (0..len).map(|_| r.u16()).collect::<Result<_, _>>()?;
            let chain = r.u64()?;
            let scores = (0..n).map(|_| r.i16()).collect::<Result<_, _>>()?;
            let winners = r.u8()?;
            let obs = ObsDigest {
                discrete: r.u64()?,
                continuous: r.u64()?,
            };
            heuristic.push(RecordedGame {
                actions,
                chain,
                scores,
                winners,
                obs,
            });
        }
        if r.at != data.len() {
            return Err(format!("{} trailing bytes", data.len() - r.at));
        }
        Ok(Self {
            header: Header {
                contract_version,
                obs_version,
                map,
                n_players,
                data_hash,
                rules_hash,
                sample_every,
            },
            random,
            random_obs,
            heuristic,
        })
    }

    pub fn load(map: &str, n_players: usize) -> Result<Self, String> {
        let path = corpus_path(map, n_players);
        let data = std::fs::read(&path).map_err(|e| format!("{}: {e}", path.display()))?;
        Self::from_bytes(&data).map_err(|e| format!("{}: {e}", path.display()))
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_wire_format_round_trips() {
        let corpus = Corpus {
            header: current_header("mini", 3),
            random: vec![RandomGame {
                steps: 9,
                chain: 0x0123_4567_89ab_cdef,
                scores: vec![-4, 0, 31],
                winners: 0b100,
            }],
            random_obs: vec![ObsDigest {
                discrete: 1,
                continuous: u64::MAX,
            }],
            heuristic: vec![RecordedGame {
                actions: vec![3, 1, 4, 1, 5],
                chain: 7,
                scores: vec![1, 2, 3],
                winners: 0b111,
                obs: ObsDigest {
                    discrete: 9,
                    continuous: 2,
                },
            }],
        };
        let bytes = corpus.to_bytes();
        assert_eq!(Corpus::from_bytes(&bytes).unwrap(), corpus);
        assert!(Corpus::from_bytes(&bytes[..bytes.len() - 1]).is_err());
        let mut longer = bytes.clone();
        longer.push(0);
        assert!(Corpus::from_bytes(&longer).is_err());
    }

    #[test]
    fn every_observation_field_is_classified_and_the_halves_tile() {
        for (map, _) in configs() {
            let mask = ObsMask::for_map(map);
            let continuous = mask.continuous.iter().filter(|&&c| c).count();
            assert!(continuous > 0 && continuous < mask.continuous.len());
        }
    }

    #[test]
    fn a_trace_is_a_pure_function_of_the_seed() {
        let engine = Live::new("mini", 2);
        let mask = ObsMask::for_map("mini");
        let a = random_trace(&engine, 3, Some(&mask)).unwrap();
        let b = random_trace(&engine, 3, Some(&mask)).unwrap();
        assert_eq!(a.chain, b.chain);
        assert_eq!(a.obs, b.obs);
        let c = random_trace(&engine, 4, Some(&mask)).unwrap();
        assert_ne!(a.chain, c.chain);
        let replayed = replay_trace(&engine, 3, &a.actions, Some(&mask)).unwrap();
        assert_eq!(replayed.chain, a.chain);
        assert_eq!(replayed.obs, a.obs);
    }

    #[test]
    fn a_replay_that_does_not_fit_the_game_is_refused() {
        let engine = Live::new("mini", 2);
        let a = random_trace(&engine, 3, None).unwrap();
        assert!(replay_trace(&engine, 3, &a.actions[..a.actions.len() - 1], None).is_err());
        let mut longer = a.actions.clone();
        longer.push(0);
        assert!(replay_trace(&engine, 3, &longer, None).is_err());
    }
}
